#!/usr/bin/env python3
"""Fieldnote: build static previews and shared fragments from original source (CSS, JS, SVG artwork)."""
from pathlib import Path
import json, shutil
R = Path(__file__).resolve().parent
css = (R/'shared/fieldnote.css').read_text() + '\n[hidden]{display:none!important}\n'
js = (R/'shared/fieldnote.js').read_text()
for dest in [R/'preview/assets', R/'wordpress/fieldnote/assets']:
    dest.mkdir(exist_ok=True, parents=True)
    for p in (R/'shared/assets').glob('*.svg'):
        shutil.copy2(p, dest/p.name)
    (dest/'fieldnote.css').write_text(css); (dest/'fieldnote.js').write_text(js)
mark = (R/'shared/assets/mark.svg').read_text().replace('<svg ', '<svg aria-hidden="true" ')
moon = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M20 14.5A8 8 0 0 1 9.5 4a8 8 0 1 0 10.5 10.5Z"/></svg>'
toggle = f'<button class="fn-icon" data-fieldnote-toggle="" aria-label="Switch to dusk reading mode" aria-pressed="false" hidden="hidden">{moon}</button>'
brand = f'<span class="fn-mark">{mark}</span><span class="fn-brand-text"><b>Fieldnote</b><small>Notes from the outside</small></span>'
topics = ['Birds', 'Plants', 'Fungi', 'Weather', 'Trails', 'Notes']
# Season strip: the current season is filled in by fieldnote.js from the visitor's clock (no request); text is the no-JS fallback.
season = '<div class="fn-season" aria-label="Season"><span>FIELD SEASON</span><span class="fn-now" data-fieldnote-season="">This season</span><span class="fn-sep" aria-hidden="true"></span><span>OBSERVE · RECORD · RETURN</span></div>'
lead = '''<section class="fn-lead-entry" aria-labelledby="fn-lead-title"><div><div class="fn-kicker">Today’s observation</div><h1 id="fn-lead-title">Look closely.<br/><em>Write it down.</em></h1><p class="fn-intro">A field journal for the birds at the feeder, the fern in the shade and the weather rolling in. Small notes, gathered patiently, become a record of a place.</p><div class="fn-actions"><a class="fn-button" href="#entries">Open the journal <span aria-hidden="true">→</span></a><a class="fn-text-link" href="NOTES">How to keep a field notebook</a></div></div><figure class="fn-plate"><span class="fn-tape" aria-hidden="true"></span><img src="ART/fern.svg" alt="Line drawing of a fern unfurling beside a small note" width="400" height="300"/><figcaption><span>Plate I · Polypodium</span><span>Shade garden</span></figcaption></figure></section>'''
banner = '''<section class="fn-banner"><div><div class="fn-kicker">An invitation</div><h2>Start your own field notebook.</h2><p>Date, place, weather, what you saw. Four lines a day is enough to begin noticing more.</p></div><a class="fn-button" href="NOTES">Read the beginner’s guide →</a></section>'''
notebook = '<section class="fn-notebook"><h2>The notebook</h2><p>Fieldnote is a place to record what you notice outdoors: carefully, slowly and in your own words.</p><a class="fn-text-link" href="ABOUT">About this journal →</a></section>'
rss = '<section class="fn-rss"><h2>Follow along</h2><p>New entries in your RSS reader, in the order they were written.</p><a class="fn-button ghost" href="FEED">Subscribe by RSS</a></section>'
posts = [
    ('sparrow', 'Birds', 'A house sparrow learns the feeder', 'Three mornings of patience, one sunflower seed and a lesson in watching without hurrying.', 'Iris Moreau', 'IM', 'Mar 14', 'Back garden', 'Clear, 6°C'),
    ('fern', 'Plants', 'The fiddleheads are back in the shade bed', 'Tight green coils, a week ahead of last year. Notes on timing, light and a patient kind of growth.', 'Tomás Reyes', 'TR', 'Mar 18', 'North border', 'Overcast, 9°C'),
    ('mushroom', 'Fungi', 'After the rain: a ring under the birches', 'Two days of rain and the woodland floor rearranged itself. What to record, and what to leave alone.', 'Iris Moreau', 'IM', 'Oct 3', 'Birch copse', 'Damp, 12°C'),
    ('weather', 'Weather', 'Reading the sky before a spring storm', 'Rising wind, a halo around the sun and a sudden quiet among the birds: a short guide to field signs.', 'Noor Haddad', 'NH', 'Apr 2', 'Hill pasture', 'Gusty, 11°C'),
    ('trail', 'Trails', 'Ridge walk: eleven kilometres and one stubborn cloud', 'A slow loop over the ridge, with notes on the path, the plants along it and when to turn back.', 'Tomás Reyes', 'TR', 'May 21', 'East ridge', 'Fair, 15°C'),
    ('oak', 'Notes', 'Pressing leaves: a beginner’s field kit', 'Paper, weight and patience. The simplest way to keep a season of leaves without damaging the tree.', 'Noor Haddad', 'NH', 'Oct 19', 'Old oak lane', 'Cool, 8°C'),
]
(R/'docs').mkdir(exist_ok=True)
(R/'docs/demo-posts.json').write_text(json.dumps(posts, indent=2, ensure_ascii=False))
def links(s):
    return (s.replace('NOTES', 'archive.html?topic=Notes').replace('ABOUT', 'about.html').replace('FEED', 'feed.xml').replace('ART/', 'assets/'))
nav = ''.join(f'<a href="archive.html?topic={t}">{t}</a>' for t in ['Birds', 'Plants', 'Trails'])
header = f'<header class="fn-header"><div class="fn-wrap fn-header-inner"><a class="fn-brand" href="index.html">{brand}</a><nav class="fn-nav" aria-label="Main navigation"><a href="archive.html">Journal</a>{nav}<a href="about.html">About</a></nav><div class="fn-tools">{toggle}<details class="fn-mobile"><summary>Menu</summary><nav aria-label="Mobile navigation"><a href="archive.html">Journal</a>{nav}<a href="about.html">About</a></nav></details></div></div></header>'
footer = f'<footer class="fn-footer"><div class="fn-wrap"><div class="fn-footer-top"><div><a class="fn-brand" href="index.html">{brand}</a><p>A journal of small observations: birds, plants, weather and the paths between them.</p></div><nav class="fn-footer-links" aria-label="Footer"><a href="about.html">About</a><a href="archive.html">All entries</a><a href="feed.xml">RSS feed</a></nav></div><div class="fn-footer-bottom"><span>Written outdoors. No tracking, no ads.</span><span class="fn-credit">Powered by <a href="https://gonk.fun/" rel="nofollow">gonk.fun</a></span></div></div></footer>'
search = '<form class="fn-search" action="archive.html" method="get" role="search"><label class="fn-sr" for="fn-search">Search entries</label><input id="fn-search" name="q" type="search" placeholder="Search the journal…"/><button type="submit" aria-label="Search entries">→</button></form>'
guide = '<nav class="fn-guide" aria-label="Field guide topics"><span>FIELD GUIDE</span>' + ''.join(f'<a class="fn-chip" href="archive.html?topic={t}">{t}</a>' for t in topics) + '</nav>'
kit = ('<aside class="fn-kit" aria-label="Field kit">' + search + links(notebook) +
       '<section><h2>Recent entries</h2><ol class="fn-list">' + ''.join(f'<li><div><a href="article.html">{p[2]}</a><small>{p[6]} · {p[7]}</small></div></li>' for p in posts[:4]) + '</ol></section>'
       '<section><h2>Browse by subject</h2><div class="fn-kit-links">' + ''.join(f'<a class="fn-chip" href="archive.html?topic={t}">{t}</a>' for t in topics) + '</div></section>' + links(rss) + '</aside>')
cards = ''.join(f'''<article class="fn-card" data-topic="{p[1]}"><a class="fn-card-art" href="article.html" tabindex="-1" aria-hidden="true"><img src="assets/{p[0]}.svg" alt="" width="400" height="300" loading="lazy"/></a><a class="fn-tag" href="archive.html?topic={p[1]}">{p[1]}</a><h3><a href="article.html">{p[2]}</a></h3><p>{p[3]}</p><div class="fn-observed"><span>Observed {p[6]}</span><span>{p[7]}</span><span>{p[8]}</span></div></article>''' for p in posts)
def shell(title, body, extra=''):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><meta name="description" content="Fieldnote, an original free nature-journal theme by Gonk Themes."/><title>{title} · Fieldnote</title><meta name="robots" content="noindex,follow"/><link rel="icon" type="image/svg+xml" href="assets/fieldnote-favicon.svg"/><link rel="stylesheet" href="assets/fieldnote.css"/><script src="assets/fieldnote.js" defer></script></head><body><a class="fn-skip" href="#main">Skip to content</a><div class="fn-demo-note">FIELDNOTE / THEME 02 — Design preview. All entries and authors are fictional examples.</div>{header}{body}{footer}{extra}</body></html>'''
home = f'<div class="fn-wrap">{links(lead)}{season}{guide}<div class="fn-content-grid"><main id="main" tabindex="-1"><div class="fn-section-heading" id="entries"><h2>Recent entries</h2><p>FROM THE NOTEBOOK</p></div><div class="fn-cards">{cards}</div><div class="fn-pagination"><span></span><a href="archive.html">All entries →</a></div></main>{kit}</div>{links(banner)}</div>'
(R/'preview/index.html').write_text(shell('Look closely. Write it down.', home))
archive = f'<div class="fn-wrap"><div class="fn-article" style="padding-bottom:20px"><div class="fn-kicker">The journal</div><h1 id="archive-title">All entries</h1><p class="fn-standfirst" id="archive-description">Every observation, newest first.</p></div>{guide}<div class="fn-content-grid"><main id="main" tabindex="-1"><div class="fn-cards" id="results">{cards}</div><div class="fn-empty" id="empty" hidden><h2>No entries found.</h2><p>Try another word or browse a different subject.</p><a class="fn-button ghost" href="archive.html">See all entries</a></div></main>{kit}</div></div>'
archivejs = '''<script>const params=new URLSearchParams(location.search),topic=params.get('topic'),q=params.get('q')||'';document.getElementById('archive-title').textContent=topic||(q?'Search: '+q:'All entries');let n=0;for(const el of document.querySelectorAll('#results .fn-card')){const show=(!topic||el.dataset.topic===topic)&&(!q||el.textContent.toLowerCase().includes(q.toLowerCase()));el.hidden=!show;if(show)n++;}document.getElementById('empty').hidden=n>0;</script>'''
(R/'preview/archive.html').write_text(shell('All entries', archive, archivejs))
article = '''<main class="fn-wrap" id="main" tabindex="-1"><article class="fn-article"><nav class="fn-breadcrumb" aria-label="Breadcrumb"><a href="index.html">Journal</a><span aria-hidden="true">/</span><a href="archive.html?topic=Birds">Birds</a></nav><div class="fn-kicker">Birds · Entry</div><h1>A house sparrow learns the feeder</h1><p class="fn-standfirst">Three mornings of patience, one sunflower seed and a lesson in watching without hurrying.</p><div class="fn-entry-meta"><span>Iris Moreau · fictional demo author</span><span>Observed Mar 14</span><span>Back garden</span><span>Clear, 6°C</span></div><figure class="fn-figure"><img src="assets/sparrow.svg" alt="Line drawing of a sparrow perched on a branch" width="400" height="300"/><figcaption>Plate II · Passer domesticus. Original theme artwork.</figcaption></figure><div class="fn-prose"><p>The feeder went up on a Monday. By Wednesday the blue tits had found it, but the sparrows kept to the hedge, chattering about it from a safe distance.</p><aside class="fn-margin"><b>Margin note</b>Sparrows often feed in groups. A single bird approaching first is worth recording: note the time.</aside><h2>Day one: the hedge.</h2><p>Six birds, all in the hawthorn. Every few minutes one would drop to the lawn beneath the feeder, pick at spilled seed and flick back up. None landed on the feeder itself.</p><blockquote>Watching without hurrying is the whole skill. The bird decides when the story starts.</blockquote><h2>Day two: the first landing.</h2><p>At 07:42 a male with a dark bib landed on the perch, took one sunflower seed and left. Thirty seconds later, two more followed.</p><table><thead><tr><th>Time</th><th>Visitors</th><th>Behaviour</th></tr></thead><tbody><tr><td>07:42</td><td>1 male</td><td>Single seed, left at once</td></tr><tr><td>07:43</td><td>2 birds</td><td>Fed together, 20 s</td></tr><tr><td>08:10</td><td>5 birds</td><td>Group feeding, some squabbling</td></tr></tbody></table><aside class="fn-margin"><b>Kit</b>A pencil, a small notebook and a watch. Binoculars help but aren’t needed at a feeder.</aside><h2>Day three: the regulars.</h2><p>By the third morning the sparrows came straight from the hedge to the feeder. The routine had changed in two days, and the notebook is the only reason I noticed.</p><ul><li>Write the date, time and weather first.</li><li>Count before you describe.</li><li>Note what changed since yesterday.</li></ul><pre><code>Date · Time · Place · Weather · What I saw</code></pre></div><div class="fn-author"><span class="fn-initials" aria-hidden="true">IM</span><div><strong>Iris Moreau</strong><p>Fictional demo author. Replace this with your own short biography.</p></div></div><div class="fn-share"><a href="https://x.com/intent/post?text=A%20house%20sparrow%20learns%20the%20feeder" target="_blank" rel="noopener noreferrer">Share on X</a><button data-fieldnote-copy="" hidden>Copy link</button></div><p><a class="fn-text-link" href="archive.html">← Back to the journal</a></p></article></main>'''
(R/'preview/article.html').write_text(shell('A house sparrow learns the feeder', article))
about = '''<main class="fn-wrap" id="main" tabindex="-1"><article class="fn-article"><div class="fn-kicker">About</div><h1>A notebook,<br/>kept in public.</h1><p class="fn-standfirst">Fieldnote is a free theme for naturalists, gardeners, walkers and anyone who likes to write down what they notice outdoors.</p><div class="fn-prose"><h2>Made for observation.</h2><p>Entries are specimen cards, with room for the date, place and weather of each observation. Articles support margin notes for the asides that always come up in the field.</p><h2>Quiet by design.</h2><p>No tracking, no external fonts and no ads. The day/dusk switch and the season label run entirely in the reader’s browser.</p><h2>Yours to change.</h2><p>Fieldnote is free software under GPL-2.0-or-later. Edit the colours, the artwork, the wording or the footer credit.</p></div><p><a class="fn-button" href="index.html">Open the journal →</a></p></article></main>'''
(R/'preview/about.html').write_text(shell('About', about))
(R/'preview/404.html').write_text(shell('Not found', '<main class="fn-wrap" id="main" tabindex="-1"><div class="fn-article"><div class="fn-kicker">404 · Off the path</div><h1>This page<br/>wandered off.</h1><p class="fn-standfirst">It may have moved. Try a search, or head back to the journal.</p>' + search + '<p><a class="fn-button" href="index.html">Back to the journal →</a></p></div></main>'))
(R/'preview/feed.xml').write_text('<?xml version="1.0"?><rss version="2.0"><channel><title>Fieldnote — design preview</title><link>https://gonk.fun/</link><description>Demo RSS document. Installed themes use the real platform feed.</description></channel></rss>')
(R/'shared/fragments.json').write_text(json.dumps(dict(lead=lead, banner=banner, notebook=notebook, rss=rss, season=season, toggle=toggle, brand=brand, topics=topics), indent=2, ensure_ascii=False))
print('Built original assets and five interactive static preview pages.')
